var BID=418.62, ASK=418.71;
var side='buy', type='limit';
var qs=function(s){return root.querySelector(s);};
var qtyEl=qs('[data-fld="qty"]'), pxEl=qs('[data-fld="px"]'), pxWrap=qs('[data-pxwrap]'), pxLab=qs('[data-pxlab]');
var costEl=qs('[data-cost]'), submit=qs('[data-submit]');
var sides=root.querySelectorAll('[data-side]'), types=root.querySelectorAll('[data-type]');
var last='', busy=false;
function money(n){return '$'+n.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});}
function qty(){var v=parseInt(String(qtyEl.value).replace(/[^0-9]/g,''),10);return isNaN(v)?0:Math.min(v,99999);}
function price(){if(type==='market'){return side==='buy'?ASK:BID;}var v=parseFloat(String(pxEl.value).replace(/[^0-9.]/g,''));return isNaN(v)?0:v;}
function render(){
  root.classList.toggle('trd-order-ticket--sell', side==='sell');
  for(var i=0;i<sides.length;i++){sides[i].setAttribute('aria-pressed', String(sides[i].getAttribute('data-side')===side));}
  for(var j=0;j<types.length;j++){types[j].setAttribute('aria-pressed', String(types[j].getAttribute('data-type')===type));}
  pxLab.textContent = type==='market' ? 'Mkt' : 'Limit';
  pxEl.readOnly = type==='market';
  pxWrap.classList.toggle('trd-order-ticket__field--off', type==='market');
  if(type==='market'){pxEl.value=(side==='buy'?ASK:BID).toFixed(2);}
  var txt=(type==='market'?'~ ':'')+money(qty()*price());
  if(txt!==last){costEl.textContent=txt;costEl.classList.remove('trd-order-ticket__cost--flash');void costEl.offsetWidth;costEl.classList.add('trd-order-ticket__cost--flash');last=txt;}
  if(!busy){submit.textContent=(side==='buy'?'Buy ':'Sell ')+qty()+' MSFT';}
}
for(var a=0;a<sides.length;a++){sides[a].addEventListener('click',function(e){side=e.currentTarget.getAttribute('data-side');render();});}
for(var b=0;b<types.length;b++){types[b].addEventListener('click',function(e){type=e.currentTarget.getAttribute('data-type');if(type==='limit'){pxEl.value=(side==='buy'?418.40:418.90).toFixed(2);}render();});}
qtyEl.addEventListener('input',render);
pxEl.addEventListener('input',render);
qtyEl.addEventListener('focus',function(){qtyEl.select();});
pxEl.addEventListener('focus',function(){if(!pxEl.readOnly){pxEl.select();}});
submit.addEventListener('click',function(){
  if(busy){return;}
  busy=true;submit.disabled=true;submit.textContent='Routing order...';
  setTimeout(function(){
    if(!root.isConnected){return;}
    submit.textContent='Sent - working '+qty()+' @ '+(type==='market'?'MKT':price().toFixed(2));
    setTimeout(function(){if(!root.isConnected){return;}busy=false;submit.disabled=false;render();},1600);
  },650);
});
render();

