var asks=[[64216.5,2.104],[64215.0,1.377],[64213.5,1.940]];
var bids=[[64212.5,0.884],[64211.0,2.516],[64209.5,1.129]];
var askRows=root.querySelectorAll('[data-asks] .trd-depth-book__row');
var bidRows=root.querySelectorAll('[data-bids] .trd-depth-book__row');
var lastEl=root.querySelector('[data-last]'), caret=root.querySelector('[data-caret]'), spreadEl=root.querySelector('[data-spread]');
var last=64213.0, prev=64213.0;
var reduce=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
function paint(){
  var cum=0, i, max=0, ac=[], bc=[];
  for(i=asks.length-1;i>=0;i--){cum+=asks[i][1];ac[i]=cum;}
  max=cum;cum=0;
  for(i=0;i<bids.length;i++){cum+=bids[i][1];bc[i]=cum;}
  if(cum>max){max=cum;}
  for(i=0;i<askRows.length;i++){
    askRows[i].querySelector('[data-sz]').textContent=asks[i][1].toFixed(3);
    askRows[i].querySelector('[data-cum]').textContent=ac[i].toFixed(2);
    askRows[i].querySelector('[data-bar]').style.width=Math.max(4,(ac[i]/max)*100).toFixed(1)+'%';
  }
  for(i=0;i<bidRows.length;i++){
    bidRows[i].querySelector('[data-sz]').textContent=bids[i][1].toFixed(3);
    bidRows[i].querySelector('[data-cum]').textContent=bc[i].toFixed(2);
    bidRows[i].querySelector('[data-bar]').style.width=Math.max(4,(bc[i]/max)*100).toFixed(1)+'%';
  }
  spreadEl.textContent=(asks[asks.length-1][0]-bids[0][0]).toFixed(1);
  lastEl.childNodes[1].nodeValue=' '+last.toLocaleString('en-US',{minimumFractionDigits:1,maximumFractionDigits:1});
  var up=last>=prev;
  caret.textContent=up?'▲':'▼';
  lastEl.classList.toggle('trd-depth-book__last--dn',!up);
}
function flash(row,dir){
  if(reduce){return;}
  var el=row.querySelector('[data-sz]'), cls='trd-depth-book__sz--'+(dir>0?'up':'dn');
  el.classList.remove('trd-depth-book__sz--up','trd-depth-book__sz--dn');
  void el.offsetWidth;
  el.classList.add(cls);
}
var timer=setInterval(function(){
  if(!root.isConnected){clearInterval(timer);return;}
  var isAsk=Math.random()<0.5;
  var book=isAsk?asks:bids;
  var idx=Math.floor(Math.random()*book.length);
  var delta=(Math.random()*0.9-0.4);
  var next=Math.max(0.12,Math.min(3.6,book[idx][1]+delta));
  var dir=next>=book[idx][1]?1:-1;
  book[idx][1]=next;
  if(Math.random()<0.35){prev=last;last=Math.random()<0.5?bids[0][0]:asks[asks.length-1][0];}
  paint();
  flash(isAsk?askRows[idx]:bidRows[idx],dir);
}, reduce?2600:900);
paint();

