.trd-position-card{--trd-pc-line:#1E2637;--trd-pc-txt:#E8EDF6;--trd-pc-dim:#7B899F;--trd-pc-up:#2FD48A;--trd-pc-dn:#FF5C6C;--trd-pc-warn:#F5A524;--trd-pc-k:var(--trd-pc-up);--trd-pc-kf:rgba(47,212,138,.16);width:100%;max-width:300px;padding:9px 10px 10px;background:linear-gradient(180deg,#151B29,#0C1017);border:1px solid var(--trd-pc-line);border-radius:12px;color:var(--trd-pc-txt);font-family:ui-sans-serif,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;font-variant-numeric:tabular-nums;font-feature-settings:"tnum" 1;-webkit-font-smoothing:antialiased}
