var ENTRY=3412.80, QTY=4.20, LIQ=2289.60, TOP=4100;
var mark=3718.62;
var hist=[];
var pnlEl=root.querySelector('[data-pnl]'), caret=root.querySelector('[data-caret]');
var pctEl=root.querySelector('[data-pct]'), markEl=root.querySelector('[data-mark]');
var line=root.querySelector('[data-line]'), area=root.querySelector('[data-area]');
var fill=root.querySelector('[data-fill]'), entryTick=root.querySelector('[data-entry]');
var reduce=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var i;
for(i=0;i<28;i++){hist.push(3412+Math.sin(i/3.1)*46+i*11.4+(i%5)*9);}
function num(n){return n.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});}
function draw(){
  var lo=Math.min.apply(null,hist), hi=Math.max.apply(null,hist), span=(hi-lo)||1;
  var pts=[], k;
  for(k=0;k<hist.length;k++){
    var x=(k/(hist.length-1))*96;
    var y=33-((hist[k]-lo)/span)*30;
    pts.push(x.toFixed(1)+','+y.toFixed(1));
  }
  line.setAttribute('points',pts.join(' '));
  area.setAttribute('points','0,36 '+pts.join(' ')+' 96,36');
}
function paint(){
  var pnl=(mark-ENTRY)*QTY;
  var pct=(mark/ENTRY-1)*100;
  var up=pnl>=0;
  root.classList.toggle('trd-position-card--dn',!up);
  caret.textContent=up?'▲':'▼';
  pnlEl.childNodes[1].nodeValue=(up?'+$':'-$')+num(Math.abs(pnl));
  pctEl.textContent=(up?'+':'-')+Math.abs(pct).toFixed(2)+'% on entry';
  markEl.textContent=mark.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
  var span=TOP-LIQ;
  fill.style.width=Math.max(0,Math.min(100,((mark-LIQ)/span)*100)).toFixed(1)+'%';
  entryTick.style.left=Math.max(0,Math.min(100,((ENTRY-LIQ)/span)*100)).toFixed(1)+'%';
  draw();
}
var timer=setInterval(function(){
  if(!root.isConnected){clearInterval(timer);return;}
  mark=Math.max(2600,Math.min(4050,mark+(Math.random()-0.48)*26));
  hist.push(mark);
  if(hist.length>28){hist.shift();}
  paint();
}, reduce?4000:1500);
