var TOTAL=500;
var done=300, avg=121.4382;
var fill=root.querySelector('[data-fill]'), doneEl=root.querySelector('[data-done]');
var avgEl=root.querySelector('[data-avg]'), avg2=root.querySelector('[data-avg2]');
var status=root.querySelector('[data-status]'), fee=root.querySelector('[data-fee]');
var reduce=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
function paint(){
  fill.style.width=((done/TOTAL)*100).toFixed(1)+'%';
  doneEl.textContent=String(done);
  avgEl.textContent=avg.toFixed(2);
  avg2.textContent=avg.toFixed(4);
  fee.textContent='-$'+(done*0.0058).toFixed(2);
  var complete=done>=TOTAL;
  status.textContent=complete?'Filled':'Partial';
  status.classList.toggle('trd-blotter-row__status--done',complete);
}
var timer=setInterval(function(){
  if(!root.isConnected){clearInterval(timer);return;}
  if(done>=TOTAL){done=300;avg=121.4382;paint();return;}
  var lot=[25,50,100][Math.floor(Math.random()*3)];
  done=Math.min(TOTAL,done+lot);
  avg=avg+(Math.random()-0.5)*0.006;
  paint();
}, reduce?3400:1500);
paint();

