js:
var rows=root.querySelectorAll('[data-inst]');
var state={};
var reduce=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var i;
for(i=0;i<rows.length;i++){
  var r=rows[i], key=r.getAttribute('data-inst');
  state[key]={el:r,dp:parseInt(r.getAttribute('data-dp'),10),open:parseFloat(r.getAttribute('data-open')),
    last:parseFloat(r.querySelector('[data-last]').textContent.replace(/,/g,'')),
    lastEl:r.querySelector('[data-last]'),chgEl:r.querySelector('[data-chg]'),arrow:r.querySelector('[data-arrow]')};
}
var keys=Object.keys(state);
function step(k){
  var s=state[k];
  var vol=s.dp===5?0.00042:(s.dp===2?1.9:38);
  var next=s.last+(Math.random()-0.5)*vol*2;
  var dir=next>=s.last?1:-1;
  s.last=next;
  s.lastEl.textContent=next.toLocaleString('en-US',{minimumFractionDigits:s.dp,maximumFractionDigits:s.dp});
  var pct=(next/s.open-1)*100;
  var up=pct>=0;
  s.arrow.textContent=up?'▲':'▼';
  s.chgEl.childNodes[1].nodeValue=(up?'+':'-')+Math.abs(pct).toFixed(2)+'%';
  s.chgEl.classList.toggle('trd-price-tape__chg--dn',!up);
  s.lastEl.classList.remove('trd-price-tape__last--up','trd-price-tape__last--dn');
  s.lastEl.classList.add(dir>0?'trd-price-tape__last--up':'trd-price-tape__last--dn');
  if(!reduce){
    s.el.classList.remove('trd-price-tape__row--up','trd-price-tape__row--dn');
    void s.el.offsetWidth;
    s.el.classList.add(dir>0?'trd-price-tape__row--up':'trd-price-tape__row--dn');
  }
}
var timer=setInterval(function(){
  if(!root.isConnected){clearInterval(timer);return;}
  if(document.hidden){return;}
  step(keys[Math.floor(Math.random()*keys.length)]);
}, reduce?2400:760);

