js:
var OPEN=34200, CLOSE=57600, PRE=14400, POST=72000;
var stateEl=root.querySelector('[data-state]'), clEl=root.querySelector('[data-cl]');
var timeEl=root.querySelector('[data-time]'), bar=root.querySelector('[data-bar]'), nowEl=root.querySelector('[data-now]');
var fmt=new Intl.DateTimeFormat('en-US',{timeZone:'America/New_York',hour12:false,weekday:'short',hour:'2-digit',minute:'2-digit',second:'2-digit'});
var DAY={Sun:0,Mon:1,Tue:2,Wed:3,Thu:4,Fri:5,Sat:6};
function ny(){
  var p=fmt.formatToParts(new Date()), o={}, i;
  for(i=0;i<p.length;i++){o[p[i].type]=p[i].value;}
  var h=parseInt(o.hour,10)%24;
  return {d:DAY[o.weekday],s:h*3600+parseInt(o.minute,10)*60+parseInt(o.second,10),hh:h,mm:o.minute,ss:o.second};
}
function wk(d){return d>=1&&d<=5;}
function toOpen(n){var k,d;for(k=0;k<8;k++){d=(n.d+k)%7;if(wk(d)&&(k>0||n.s<OPEN)){return k*86400+OPEN-n.s;}}return 0;}
function sinceClose(n){var k,d;for(k=0;k<8;k++){d=((n.d-k)%7+7)%7;if(wk(d)&&(k>0||n.s>=CLOSE)){return k*86400+n.s-CLOSE;}}return 3600;}
function pad(v){return v<10?'0'+v:''+v;}
function clock(sec){
  var d=Math.floor(sec/86400), r=sec%86400;
  var h=Math.floor(r/3600), m=Math.floor((r%3600)/60), s=r%60;
  return (d>0?d+'d ':'')+pad(h)+':'+pad(m)+':'+pad(s);
}
function tick(){
  if(!root.isConnected){clearInterval(timer);return;}
  var n=ny(), mode, left, prog;
  root.classList.remove('trd-session-pill--open','trd-session-pill--post','trd-session-pill--closed');
  if(wk(n.d)&&n.s>=OPEN&&n.s<CLOSE){
    mode='Open'; left=CLOSE-n.s; prog=(n.s-OPEN)/(CLOSE-OPEN);
    clEl.textContent='Closes in'; root.classList.add('trd-session-pill--open');
  }else{
    left=toOpen(n);
    var since=sinceClose(n);
    prog=since/(since+left);
    clEl.textContent='Opens in';
    if(wk(n.d)&&n.s>=PRE&&n.s<OPEN){mode='Pre-market';}
    else if(wk(n.d)&&n.s>=CLOSE&&n.s<POST){mode='After hours'; root.classList.add('trd-session-pill--post');}
    else{mode='Closed'; root.classList.add('trd-session-pill--closed');}
  }
  stateEl.textContent=mode;
  timeEl.textContent=clock(left);
  bar.style.width=(Math.max(0,Math.min(1,prog))*100).toFixed(2)+'%';
  nowEl.textContent=pad(n.hh)+':'+n.mm+':'+n.ss+' ET';
}
var timer=setInterval(tick,1000);
tick();

