var MARK=64120, SIZE=0.35, MMR=0.004;
var range=root.querySelector('[data-range]'), val=root.querySelector('[data-val]');
var marginEl=root.querySelector('[data-margin]'), liqEl=root.querySelector('[data-liq]');
var sign=root.querySelector('[data-sign]'), msg=root.querySelector('[data-msg]');
var ticks=root.querySelectorAll('[data-set]');
function paint(){
  var lev=parseInt(range.value,10);
  var liq=MARK*(1-1/lev+MMR);
  var dist=(MARK-liq)/MARK*100;
  var margin=(MARK*SIZE)/lev;
  root.style.setProperty('--trd-lv-p',((lev-1)/49*100).toFixed(1)+'%');
  val.textContent=lev+'×';
  marginEl.textContent='$'+margin.toLocaleString('en-US',{maximumFractionDigits:0});
  liqEl.textContent=liq.toLocaleString('en-US',{minimumFractionDigits:1,maximumFractionDigits:1});
  root.classList.toggle('trd-lev-slider--warn',lev>=12&&lev<25);
  root.classList.toggle('trd-lev-slider--risk',lev>=25);
  var tone = lev>=25 ? '⚠ Danger' : (lev>=12 ? '△ Caution' : '● Steady');
  var parts=tone.split(' ');
  sign.textContent=parts[0];
  msg.textContent=parts[1]+' · liquidation '+dist.toFixed(1)+'% below mark';
  for(var i=0;i<ticks.length;i++){
    ticks[i].classList.toggle('trd-lev-slider__tick--on',parseInt(ticks[i].getAttribute('data-set'),10)===lev);
  }
}
range.addEventListener('input',paint);
for(var t=0;t<ticks.length;t++){
  ticks[t].addEventListener('click',function(e){range.value=e.currentTarget.getAttribute('data-set');paint();range.focus();});
}
paint();

