var arm=root.querySelector('[data-arm]'), cfm=root.querySelector('[data-confirm]');
var yes=root.querySelector('[data-yes]'), no=root.querySelector('[data-no]');
var busy=root.querySelector('[data-busy]'), done=root.querySelector('[data-done]');
var note=root.querySelector('[data-note]'), drain=root.querySelector('[data-drain]');
var NOTE='Reduce-only · est. slippage 0.04% · fee $0.98';
var t1=null, t2=null, t3=null;
function show(which){
  arm.hidden = which!=='idle';
  cfm.hidden = which!=='armed';
  busy.hidden = which!=='busy';
  done.hidden = which!=='done';
}
function clear(){clearTimeout(t1);clearTimeout(t2);clearTimeout(t3);}
function idle(focus){
  clear();show('idle');note.textContent=NOTE;
  if(focus&&root.contains(document.activeElement)){arm.focus();}
}
arm.addEventListener('click',function(){
  clear();show('armed');
  note.textContent='Press confirm within 4s · Esc to cancel';
  drain.style.animation='none';void drain.offsetWidth;drain.style.animation='';
  yes.focus();
  t1=setTimeout(function(){if(root.isConnected){idle(true);}},4000);
});
no.addEventListener('click',function(){idle(true);});
yes.addEventListener('click',function(){
  clear();show('busy');note.textContent='Sending reduce-only market order';
  t2=setTimeout(function(){
    if(!root.isConnected){return;}
    show('done');note.textContent='Filled 14:42:11 · position flat';
    t3=setTimeout(function(){if(root.isConnected){idle(false);}},4200);
  },1100);
});
root.addEventListener('keydown',function(e){
  if(e.key==='Escape'&&!cfm.hidden){e.stopPropagation();idle(true);}
});
show('idle');

