var d = root.dataset;
var qtyEl = root.querySelector('.trd-order-ticket-v2__input--qty');
var pxEl = root.querySelector('.trd-order-ticket-v2__input--px');
var pxField = root.querySelector('.trd-order-ticket-v2__field--px');
var pxLbl = root.querySelector('.trd-order-ticket-v2__lbl--px');
var estEl = root.querySelector('.trd-order-ticket-v2__estval');
var estLbl = root.querySelector('.trd-order-ticket-v2__estlbl');
var lastEl = root.querySelector('.trd-order-ticket-v2__lastval');
var submit = root.querySelector('.trd-order-ticket-v2__submit');
var sideBtns = root.querySelectorAll('.trd-order-ticket-v2__seg--side .trd-order-ticket-v2__segbtn');
var typeBtns = root.querySelectorAll('.trd-order-ticket-v2__seg--type .trd-order-ticket-v2__segbtn');
var last = 182.44, limitPx = 182.10, prev = null, sent = false, i;
function nf(n){ return n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }
function applyType(){
  var mkt = d.type === 'market';
  pxEl.disabled = mkt;
  pxLbl.textContent = mkt ? 'Mkt' : 'Limit';
  pxField.classList.toggle('trd-order-ticket-v2__field--off', mkt);
  pxEl.value = (mkt ? last : limitPx).toFixed(2);
}
function paint(){
  var buy = d.side === 'buy', mkt = d.type === 'market';
  var q = Math.max(0, Math.floor(Number(qtyEl.value) || 0));
  var p = mkt ? last : (Number(pxEl.value) || 0);
  var gross = q * p, net = buy ? gross * 1.0004 : gross * 0.9996;
  estLbl.textContent = buy ? 'Est. cost' : 'Est. proceeds';
  estEl.textContent = nf(net);
  if (!sent) submit.textContent = (buy ? 'Buy' : 'Sell') + ' NVDA';
  for (i = 0; i < sideBtns.length; i++) sideBtns[i].setAttribute('aria-pressed', String(sideBtns[i].dataset.side === d.side));
  for (i = 0; i < typeBtns.length; i++) typeBtns[i].setAttribute('aria-pressed', String(typeBtns[i].dataset.type === d.type));
  if (prev !== null && Math.abs(net - prev) > 0.004) {
    estEl.classList.remove('trd-order-ticket-v2__estval--tick');
    void estEl.offsetWidth;
    estEl.classList.add('trd-order-ticket-v2__estval--tick');
  }
  prev = net;
}
for (i = 0; i < sideBtns.length; i++) sideBtns[i].addEventListener('click', function(){ d.side = this.dataset.side; sent = false; root.classList.remove('trd-order-ticket-v2--sent'); paint(); });
for (i = 0; i < typeBtns.length; i++) typeBtns[i].addEventListener('click', function(){ d.type = this.dataset.type; applyType(); paint(); });
qtyEl.addEventListener('input', paint);
pxEl.addEventListener('input', function(){ if (d.type !== 'market') limitPx = Number(pxEl.value) || 0; paint(); });
submit.addEventListener('click', function(){
  sent = true;
  root.classList.add('trd-order-ticket-v2--sent');
  submit.textContent = 'Order sent';
  setTimeout(function(){ sent = false; root.classList.remove('trd-order-ticket-v2--sent'); paint(); }, 1300);
});
var tick = setInterval(function(){
  if (!root.isConnected) { clearInterval(tick); return; }
  var next = Math.round((last + (Math.random() - 0.485) * 0.18) * 100) / 100;
  var up = next >= last;
  last = next;
  lastEl.textContent = next.toFixed(2);
  lastEl.classList.remove('trd-order-ticket-v2__lastval--up', 'trd-order-ticket-v2__lastval--dn');
  void lastEl.offsetWidth;
  lastEl.classList.add(up ? 'trd-order-ticket-v2__lastval--up' : 'trd-order-ticket-v2__lastval--dn');
  if (d.type === 'market') { pxEl.value = last.toFixed(2); paint(); }
}, 1600);
applyType(); paint();

