var rows = root.querySelectorAll('.trd-depth-book-v2__row');
var readout = root.querySelector('.trd-depth-book-v2__readout');
var midEl = root.querySelector('.trd-depth-book-v2__mid');
var sprdEl = root.querySelector('.trd-depth-book-v2__sprd');
var bpEl = root.querySelector('.trd-depth-book-v2__bp');
var offAsk = [0.55, 1.65, 2.55, 3.85], offBid = [0.55, 1.45, 2.35, 3.65];
var szAsk = [1.233, 0.861, 0.524, 0.312], szBid = [0.284, 0.612, 0.948, 1.421];
var mid = 63487.60, pinned = null, i;
function nf(n, dp){ return n.toLocaleString('en-US', { minimumFractionDigits: dp, maximumFractionDigits: dp }); }
function jitter(v){ return Math.max(0.04, v * (0.78 + Math.random() * 0.46)); }
function paint(){
  var cumA = [], cumB = [], a = 0, b = 0, max = 0;
  for (i = 0; i < 4; i++) { a += szAsk[i]; cumA.push(a); b += szBid[i]; cumB.push(b); }
  max = Math.max(a, b);
  for (i = 0; i < rows.length; i++) {
    var r = rows[i], ask = r.dataset.kind === 'ask', k = Number(r.dataset.idx);
    var px = ask ? mid + offAsk[k] : mid - offBid[k];
    var sz = ask ? szAsk[k] : szBid[k];
    var cum = ask ? cumA[k] : cumB[k];
    r.querySelector('.trd-depth-book-v2__px').textContent = nf(px, 2);
    r.querySelector('.trd-depth-book-v2__sz').textContent = nf(sz, 3);
    r.querySelector('.trd-depth-book-v2__cum').textContent = nf(cum, 3);
    r.style.setProperty('--trd-db-d', (cum / max).toFixed(3));
    r.setAttribute('aria-label', (ask ? 'Ask ' : 'Bid ') + nf(px, 2) + ', size ' + nf(sz, 3) + ' BTC, cumulative ' + nf(cum, 3));
  }
  var sprd = offAsk[0] + offBid[0];
  midEl.textContent = nf(mid, 2);
  sprdEl.textContent = sprd.toFixed(2);
  bpEl.textContent = (sprd / mid * 10000).toFixed(2);
}
function describe(r){
  if (!r) { readout.textContent = 'Cumulative depth'; return; }
  var ask = r.dataset.kind === 'ask';
  readout.textContent = (ask ? 'Buy ' : 'Sell ') + r.querySelector('.trd-depth-book-v2__cum').textContent + ' BTC @ ' + r.querySelector('.trd-depth-book-v2__px').textContent;
}
for (i = 0; i < rows.length; i++) {
  rows[i].addEventListener('mouseenter', function(){ describe(this); });
  rows[i].addEventListener('focus', function(){ describe(this); });
  rows[i].addEventListener('mouseleave', function(){ describe(pinned); });
  rows[i].addEventListener('blur', function(){ describe(pinned); });
  rows[i].addEventListener('click', function(){
    var was = pinned === this;
    for (var j = 0; j < rows.length; j++) rows[j].classList.remove('trd-depth-book-v2__row--sel');
    pinned = was ? null : this;
    if (pinned) pinned.classList.add('trd-depth-book-v2__row--sel');
    describe(pinned);
  });
}
var tick = setInterval(function(){
  if (!root.isConnected) { clearInterval(tick); return; }
  for (var j = 0; j < 4; j++) {
    if (Math.random() < 0.55) szAsk[j] = Math.round(jitter(szAsk[j]) * 1000) / 1000;
    if (Math.random() < 0.55) szBid[j] = Math.round(jitter(szBid[j]) * 1000) / 1000;
  }
  mid = Math.round((mid + (Math.random() - 0.5) * (Math.random() < 0.12 ? 2.6 : 0.5)) * 20) / 20;
  paint();
  if (pinned) describe(pinned);
}, 900);
paint();

