var entry = 2671.40, qty = 1.75, N = 24;
var pnlVal = root.querySelector('.trd-position-pnl__pnlval');
var pctEl = root.querySelector('.trd-position-pnl__pct');
var arrow = root.querySelector('.trd-position-pnl__arrow');
var markEl = root.querySelector('.trd-position-pnl__v--mark');
var line = root.querySelector('.trd-position-pnl__line');
var area = root.querySelector('.trd-position-pnl__area');
var eline = root.querySelector('.trd-position-pnl__entry');
var series = [], v = entry - 22, i;
for (i = 0; i < N; i++) { v += (Math.random() - 0.42) * 26; series.push(v); }
var shift = 2776.90 - series[N - 1];
for (i = 0; i < N; i++) series[i] += shift;
function nf(n){ return n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }
function paint(){
  var mark = series[series.length - 1];
  var pnl = (mark - entry) * qty, pct = (mark / entry - 1) * 100, up = pnl >= 0;
  root.dataset.dir = up ? 'up' : 'dn';
  arrow.textContent = up ? '▲' : '▼';
  pnlVal.textContent = (up ? '+' : '-') + nf(Math.abs(pnl));
  pctEl.textContent = (up ? '+' : '-') + Math.abs(pct).toFixed(2) + '%';
  markEl.textContent = nf(mark);
  var lo = Math.min(entry, Math.min.apply(null, series));
  var hi = Math.max(entry, Math.max.apply(null, series));
  var rng = (hi - lo) || 1, pts = '', step = 96 / (N - 1);
  for (i = 0; i < N; i++) pts += (i * step).toFixed(2) + ',' + (37 - ((series[i] - lo) / rng) * 33).toFixed(2) + ' ';
  line.setAttribute('points', pts.trim());
  area.setAttribute('points', '0,40 ' + pts.trim() + ' 96,40');
  var ey = (37 - ((entry - lo) / rng) * 33).toFixed(2);
  eline.setAttribute('y1', ey); eline.setAttribute('y2', ey);
}
var tick = setInterval(function(){
  if (!root.isConnected) { clearInterval(tick); return; }
  var prev = series[series.length - 1];
  var next = prev + (Math.random() - 0.47) * 22;
  series.push(next); series.shift();
  paint();
  markEl.classList.remove('trd-position-pnl__v--up', 'trd-position-pnl__v--dn');
  void markEl.offsetWidth;
  markEl.classList.add(next >= prev ? 'trd-position-pnl__v--up' : 'trd-position-pnl__v--dn');
  setTimeout(function(){ markEl.classList.remove('trd-position-pnl__v--up', 'trd-position-pnl__v--dn'); }, 450);
}, 1500);
paint();

