var btn = root.querySelector('.trd-blotter-row-v2__row');
var detail = root.querySelector('.trd-blotter-row-v2__detail');
var fill = root.querySelector('.trd-blotter-row-v2__fill');
var doneEl = root.querySelector('.trd-blotter-row-v2__done');
var pill = root.querySelector('.trd-blotter-row-v2__pill');
var pxEl = root.querySelector('.trd-blotter-row-v2__px');
var avgEl = root.querySelector('.trd-blotter-row-v2__dd--avg');
var slipEl = root.querySelector('.trd-blotter-row-v2__dd--slip');
var feeEl = root.querySelector('.trd-blotter-row-v2__dd--fee');
var total = 1200, done = 840, notional = 840 * 228.39, arrival = 228.41;
function nf(n, dp){ return n.toLocaleString('en-US', { minimumFractionDigits: dp, maximumFractionDigits: dp }); }
function setOpen(open){
  root.classList.toggle('trd-blotter-row-v2--open', open);
  btn.setAttribute('aria-expanded', String(open));
  detail.setAttribute('aria-hidden', String(!open));
}
function paint(){
  var avg = done ? notional / done : arrival;
  var slip = avg - arrival;
  doneEl.textContent = nf(done, 0);
  pxEl.textContent = nf(arrival, 2);
  avgEl.textContent = nf(avg, 2);
  slipEl.textContent = (slip < -0.004 ? '-' : (slip > 0.004 ? '+' : '')) + nf(Math.abs(slip), 2);
  slipEl.classList.toggle('trd-blotter-row-v2__dd--bad', slip > 0.004);
  feeEl.textContent = nf(done * 0.0035, 2);
  fill.style.width = (done / total * 100).toFixed(1) + '%';
  var st = done >= total ? 'filled' : (done > 0 ? 'partial' : 'working');
  root.dataset.status = st;
  pill.textContent = st === 'filled' ? 'Filled' : (st === 'partial' ? 'Partial' : 'Working');
  btn.setAttribute('aria-label', 'Buy 1,200 AAPL at 228.41, ' + nf(done, 0) + ' filled, ' + pill.textContent);
}
btn.addEventListener('click', function(){ setOpen(btn.getAttribute('aria-expanded') !== 'true'); });
var tick = null;
function step(){
  if (!root.isConnected) { clearInterval(tick); return; }
  var chunk = Math.min(total - done, 60 + Math.floor(Math.random() * 220));
  var px = Math.round((arrival + (Math.random() - 0.55) * 0.06) * 100) / 100;
  done += chunk; notional += chunk * px;
  paint();
  if (done >= total) {
    clearInterval(tick); tick = null;
    root.classList.add('trd-blotter-row-v2--flash');
    setTimeout(function(){ root.classList.remove('trd-blotter-row-v2--flash'); }, 700);
    setTimeout(function(){
      if (!root.isConnected) return;
      done = 0; notional = 0; paint();
      tick = setInterval(step, 1700);
    }, 3600);
  }
}
tick = setInterval(step, 1700);
setOpen(true); paint();

