js:
var rows = root.querySelectorAll('.trd-tape-flash__row');
var calm = false;
try { calm = window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (e) {}
function nf(n){ return n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }
function print(row){
  var px = Number(row.dataset.px), prev = Number(row.dataset.prev);
  var step = px * (0.0004 + Math.random() * 0.0016) * (Math.random() < 0.5 ? -1 : 1);
  var next = Math.round((px + step) * 100) / 100;
  var up = next >= px;
  row.dataset.px = String(next);
  var pct = (next / prev - 1) * 100;
  row.dataset.dir = pct >= 0 ? 'up' : 'dn';
  row.querySelector('.trd-tape-flash__px').textContent = nf(next);
  row.querySelector('.trd-tape-flash__arw').textContent = pct >= 0 ? '▲' : '▼';
  row.querySelector('.trd-tape-flash__pct').textContent = (pct >= 0 ? '+' : '-') + Math.abs(pct).toFixed(2) + '%';
  if (calm) return;
  row.classList.remove('trd-tape-flash__row--up', 'trd-tape-flash__row--dn');
  void row.offsetWidth;
  row.classList.add(up ? 'trd-tape-flash__row--up' : 'trd-tape-flash__row--dn');
}
var tick = setInterval(function(){
  if (!root.isConnected) { clearInterval(tick); return; }
  print(rows[Math.floor(Math.random() * rows.length)]);
  if (Math.random() < 0.35) print(rows[Math.floor(Math.random() * rows.length)]);
}, 850);

