var stateEl = root.querySelector('.trd-session-pill-v2__state');
var lblEl = root.querySelector('.trd-session-pill-v2__cdlbl');
var valEl = root.querySelector('.trd-session-pill-v2__cdval');
var nowEl = root.querySelector('.trd-session-pill-v2__now');
var PRE = 14400, OPEN = 34200, CLOSE = 57600, AFTER = 72000;
var dtf = null;
try { dtf = new Intl.DateTimeFormat('en-US', { timeZone: 'America/New_York', hour12: false, weekday: 'short', hour: '2-digit', minute: '2-digit', second: '2-digit' }); } catch (e) { dtf = null; }
function ny(){
  if (!dtf) { var l = new Date(); return { dow: l.getDay(), secs: l.getHours() * 3600 + l.getMinutes() * 60 + l.getSeconds() }; }
  var p = {}, parts = dtf.formatToParts(new Date()), i;
  for (i = 0; i < parts.length; i++) p[parts[i].type] = parts[i].value;
  var map = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 };
  return { dow: map[p.weekday], secs: (parseInt(p.hour, 10) % 24) * 3600 + parseInt(p.minute, 10) * 60 + parseInt(p.second, 10) };
}
function toNextOpen(dow, s){
  if (dow >= 1 && dow <= 5 && s < OPEN) return OPEN - s;
  var days = 1, nd = (dow + 1) % 7;
  while (nd === 0 || nd === 6) { days++; nd = (nd + 1) % 7; }
  return (86400 - s) + (days - 1) * 86400 + OPEN;
}
function pad(n){ return (n < 10 ? '0' : '') + n; }
function fmt(t){
  var d = Math.floor(t / 86400), h = Math.floor((t % 86400) / 3600), m = Math.floor((t % 3600) / 60), s = t % 60;
  return (d > 0 ? d + 'd ' : '') + pad(h) + ':' + pad(m) + ':' + pad(s);
}
function paint(){
  var n = ny(), s = n.secs, weekend = (n.dow === 0 || n.dow === 6);
  var state = 'closed', label = 'Opens in', left = toNextOpen(n.dow, s), name = 'Closed';
  if (!weekend && s >= OPEN && s < CLOSE) { state = 'open'; name = 'Open'; label = 'Closes in'; left = CLOSE - s; }
  else if (!weekend && s >= PRE && s < OPEN) { state = 'pre'; name = 'Pre-market'; label = 'Opens in'; left = OPEN - s; }
  else if (!weekend && s >= CLOSE && s < AFTER) { state = 'after'; name = 'After hours'; label = 'Opens in'; }
  root.dataset.state = state;
  stateEl.textContent = name;
  lblEl.textContent = label;
  valEl.textContent = fmt(left);
  var p = Math.max(0, Math.min(1, (s - PRE) / (AFTER - PRE)));
  nowEl.style.left = (p * 100).toFixed(2) + '%';
  root.setAttribute('aria-label', 'NYSE ' + name + ', ' + label.toLowerCase() + ' ' + fmt(left));
}
var tick = setInterval(function(){
  if (!root.isConnected) { clearInterval(tick); return; }
  paint();
}, 1000);
paint();

