var range = root.querySelector('.trd-leverage-dial__range');
var levEl = root.querySelector('.trd-leverage-dial__levval');
var marginEl = root.querySelector('.trd-leverage-dial__v--margin');
var liqEl = root.querySelector('.trd-leverage-dial__v--liq');
var bufEl = root.querySelector('.trd-leverage-dial__v--buf');
var warnEl = root.querySelector('.trd-leverage-dial__warntxt');
var icoEl = root.querySelector('.trd-leverage-dial__ico');
var entry = 62905.20, size = 0.42, notional = entry * size, maint = 0.005;
function nf(n, dp){ return n.toLocaleString('en-US', { minimumFractionDigits: dp, maximumFractionDigits: dp }); }
function paint(){
  var lev = Number(range.value);
  var min = Number(range.min), max = Number(range.max);
  var liq = entry * (1 - 1 / lev + maint);
  var buf = (liq / entry - 1) * 100;
  root.style.setProperty('--tld-p', ((lev - min) / (max - min)).toFixed(4));
  levEl.textContent = String(lev);
  marginEl.textContent = nf(notional / lev, 2);
  liqEl.textContent = nf(liq, 2);
  bufEl.textContent = buf.toFixed(1) + '%';
  var risk = lev >= 25 ? 'danger' : (lev >= 10 ? 'warn' : 'safe');
  root.dataset.risk = risk;
  icoEl.textContent = risk === 'safe' ? 'i' : '!';
  warnEl.textContent = risk === 'danger'
    ? 'Danger: a ' + Math.abs(buf).toFixed(1) + '% move against you liquidates the position.'
    : (risk === 'warn'
      ? 'High leverage. Only ' + Math.abs(buf).toFixed(1) + '% of room before liquidation.'
      : 'Liquidation sits ' + Math.abs(buf).toFixed(1) + '% below mark.');
  range.setAttribute('aria-valuetext', lev + 'x leverage, liquidation ' + nf(liq, 2) + ', ' + Math.abs(buf).toFixed(1) + ' percent below mark');
}
range.addEventListener('input', paint);
range.addEventListener('change', paint);
paint();

