js:
var start = root.querySelector('.trd-close-confirm__btn--start');
var cancel = root.querySelector('.trd-close-confirm__btn--cancel');
var go = root.querySelector('.trd-close-confirm__btn--go');
var goTxt = root.querySelector('.trd-close-confirm__gotxt');
var timer = root.querySelector('.trd-close-confirm__timer');
var msg = root.querySelector('.trd-close-confirm__msg');
var reset = root.querySelector('.trd-close-confirm__btn--reset');
var real = root.querySelector('.trd-close-confirm__real');
var WINDOW = 4000, deadline = 0, drain = null, work = null;
function stop(){ if (drain) { clearInterval(drain); drain = null; } }
function idle(m){
  stop();
  root.dataset.stage = 'idle';
  go.disabled = false;
  goTxt.textContent = 'Confirm market close';
  timer.style.width = '100%';
  msg.textContent = m || 'Market close, reduce-only. Two taps.';
}
function arm(){
  root.dataset.stage = 'confirm';
  deadline = Date.now() + WINDOW;
  timer.style.width = '100%';
  msg.textContent = 'Confirm within 4s to close 42.0 SOL at market.';
  go.focus();
  stop();
  drain = setInterval(function(){
    if (!root.isConnected) { stop(); return; }
    var rem = deadline - Date.now();
    timer.style.width = Math.max(0, rem / WINDOW * 100).toFixed(1) + '%';
    if (rem <= 0) idle('Confirmation timed out. Nothing was sent.');
  }, 60);
}
start.addEventListener('click', arm);
cancel.addEventListener('click', function(){ idle('Cancelled. Position left open.'); start.focus(); });
go.addEventListener('click', function(){
  if (go.disabled) return;
  stop();
  root.dataset.stage = 'working';
  go.disabled = true;
  goTxt.textContent = 'Closing 42.0 SOL...';
  timer.style.width = '100%';
  msg.textContent = 'Routing reduce-only market order.';
  work = setTimeout(function(){
    root.dataset.stage = 'done';
    real.textContent = '+128.44';
    msg.textContent = 'Filled 42.0 SOL at 63.18 average. Position flat.';
  }, 950);
});
reset.addEventListener('click', function(){ if (work) clearTimeout(work); idle(); start.focus(); });
root.addEventListener('keydown', function(ev){
  if (ev.key === 'Escape' && root.dataset.stage === 'confirm') { idle('Cancelled. Position left open.'); start.focus(); }
});
idle();
